from __future__ import annotations

import json
from collections.abc import AsyncIterator
from typing import TYPE_CHECKING, Any

from rasa.builder.copilot.pydantic_ai import ag_ui_events
from rasa.builder.copilot.pydantic_ai.hooks import build_commit_hook
from rasa.builder.copilot.pydantic_ai.model_registry import validate_model
from rasa.builder.copilot.pydantic_ai.types import (
    Message,
    ReasoningEffort,
    RunRequest,
    ThinkingPref,
)

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.agent import PydanticAICopilot
    from rasa.builder.project_generator import ProjectGenerator


def encode_sse_event(event: dict[str, Any]) -> str:
    """Encode one AG-UI event as an SSE data frame (data-only lines)."""
    return f"data: {json.dumps(event, separators=(',', ':'))}\n\n"


async def stream_copilot_v2_sse(
    runtime: PydanticAICopilot,
    payload: dict[str, Any],
    project_generator: "ProjectGenerator",
    email: str,
) -> AsyncIterator[str]:
    """Convert an AG-UI request payload into SSE frames.

    Wires the Copilot v2 end-of-run hook (commit changed files) so the web
    layer only supplies request-scoped dependencies, not runtime behavior.
    """
    try:
        run_request = _parse_payload(payload)
    except (KeyError, TypeError, ValueError) as exc:
        yield encode_sse_event(
            ag_ui_events.run_error(str(exc), code=type(exc).__name__)
        )
        return

    # The project directory is owned by the server, never the client: the file
    # tools and the commit hook must operate on the same path to avoid writing
    # one directory while committing another.
    project_path = str(project_generator.project_folder)
    end_of_run_hook = build_commit_hook(project_generator, email)
    async for event in runtime.stream_ag_ui_events(
        run_request, project_path=project_path, end_of_run_hook=end_of_run_hook
    ):
        yield encode_sse_event(event)


def _parse_payload(payload: dict[str, Any]) -> RunRequest:
    """Parse an AG-UI RunAgentInput-shaped payload."""
    raw_messages = payload.get("messages", [])
    if not isinstance(raw_messages, list):
        raise TypeError("messages must be a list")

    messages = tuple(
        Message(role=str(msg["role"]), content=str(msg.get("content", "")))
        for msg in raw_messages
        if str(msg.get("role", "")) in {"user", "assistant", "system"}
        and str(msg.get("content", "")).strip()
    )
    raw_state = payload.get("state", {})
    state: dict[str, Any] = dict(raw_state) if isinstance(raw_state, dict) else {}

    thread_id = payload.get("thread_id", payload.get("threadId"))
    run_id = payload.get("run_id", payload.get("runId"))
    if thread_id is None:
        raise KeyError("thread_id")
    if run_id is None:
        raise KeyError("run_id")

    return RunRequest(
        thread_id=str(thread_id),
        run_id=str(run_id),
        messages=messages,
        state=state,
        model=_parse_model(state),
        thinking=_parse_thinking(state),
    )


def _parse_model(state: dict[str, Any]) -> str | None:
    """Extract and validate the requested model id from AG-UI run state.

    Raises:
        ValueError: If the model id names a provider Copilot v2 won't drive.
    """
    model = state.get("model")
    if model is None:
        return None
    model_str = str(model).strip()
    if not model_str:
        return None
    return validate_model(model_str)


def _parse_thinking(state: dict[str, Any]) -> ThinkingPref:
    """Extract thinking preferences from AG-UI run state."""
    raw = state.get("thinking")
    if not isinstance(raw, dict):
        return ThinkingPref()

    # Enable only on a real JSON boolean ``true``. A stringy ``"false"`` would be
    # truthy under ``bool()``, so fail closed on anything that isn't literally
    # ``True`` (the frontend sends a JSON boolean).
    enabled = raw.get("enabled") is True
    budget_raw = raw.get("budget", ThinkingPref().budget)
    try:
        budget = int(budget_raw)
    except (TypeError, ValueError):
        budget = ThinkingPref().budget

    effort_raw = str(raw.get("effort", ReasoningEffort.MEDIUM.value))
    try:
        effort = ReasoningEffort(effort_raw)
    except ValueError:
        effort = ReasoningEffort.MEDIUM
    return ThinkingPref(enabled=enabled, budget=budget, effort=effort)
